powered.source:
void setup() {
  pinMode(5, OUTPUT);
  digitalWrite(5, LOW);
  delay(250);
  digitalWrite(5, HIGH);
  delay(1200);
  for (int cycle = 0; cycle < 8; cycle++) {
    digitalWrite(5, LOW);
    delayMicroseconds(320);
    digitalWrite(5, HIGH);
    delayMicroseconds(180);
  }
  delay(4550);
  digitalWrite(5, LOW);
}

void loop() {
  delay(1000);
}

